import{_ as e,o as a,c as o,a2 as n}from"./chunks/framework.sN6AQ-fu.js";const p=JSON.parse('{"title":"Tasks","description":"","frontmatter":{},"headers":[],"relativePath":"suite/tasks.md","filePath":"suite/tasks.md"}'),r={name:"suite/tasks.md"};function s(d,t,h,i,c,g){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h1><p>Feedback from the team becomes tasks for coding agents. You approve an agent&#39;s plan before it changes code, and check the change when it&#39;s done. Tasks live as one JSON file each in the robot repo&#39;s <code>tools/mayhem/review/</code> folder, so agents and teammates see them with the code. Choose the robot code folder first.</p><h2 id="giving-feedback" tabindex="-1">Giving feedback <a class="header-anchor" href="#giving-feedback" aria-label="Permalink to &quot;Giving feedback&quot;">​</a></h2><ul><li><strong>Add feedback</strong>: thumbs up, thumbs down or a comment, with a short title and what should change.</li><li><strong>Pit note</strong>: the one-line box at the top. Type and press Save.</li><li><strong>Driver form</strong>: a quick post-match form (ratings, yes/no questions, what broke, what to change), attached to that match&#39;s log.</li><li><strong>Right-click → Make this an agent task</strong> almost anywhere in the app: an auto step, a state, a log moment, a Changes finding, a spot in a sim replay. The task records exactly what you pointed at.</li></ul><p>Add your name so the agent and team know who to ask. In the browser, feedback downloads as a file to put in <code>tools/mayhem/review/</code>.</p><h2 id="the-board" tabindex="-1">The board <a class="header-anchor" href="#the-board" aria-label="Permalink to &quot;The board&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th><th>You</th></tr></thead><tbody><tr><td><strong>New</strong></td><td>Waiting for an agent.</td><td>Can decline.</td></tr><tr><td><strong>Agent planning</strong></td><td>An agent took it.</td><td></td></tr><tr><td><strong>Plan to approve</strong></td><td>The agent wrote a plan.</td><td><strong>Approve plan</strong> or <strong>Ask for a different plan</strong>, with a note.</td></tr><tr><td><strong>Agent working</strong></td><td>Plan approved, code changing.</td><td></td></tr><tr><td><strong>Ready to check</strong></td><td>The change is done.</td><td><strong>See what changed on the robot</strong> opens Changes for it; then <strong>Accept the change</strong> or <strong>Not right, reopen</strong>.</td></tr><tr><td><strong>Done</strong></td><td>Accepted, declined or just noted.</td><td>Can reopen.</td></tr></tbody></table><p>The Tasks tab badge counts plans and changes waiting for you. Each card shows its kind, author, what it&#39;s pinned to, the agent, and the risk level of its latest change. Open a card for the full text, the plan, each change with its findings, and the history.</p><h2 id="connect-an-agent" tabindex="-1">Connect an agent <a class="header-anchor" href="#connect-an-agent" aria-label="Permalink to &quot;Connect an agent&quot;">​</a></h2><p>Expand <strong>Connect an agent</strong> at the bottom of the page:</p><table tabindex="0"><thead><tr><th>Panel</th><th>What&#39;s there</th></tr></thead><tbody><tr><td><strong>Share this project with an agent</strong></td><td>A copyable brief describing the project.</td></tr><tr><td><strong>Live file link</strong></td><td><strong>Save project file</strong> links the project to a file in the robot repo; see <a href="/Mayhem/suite/projects#live-file-link-desktop">projects</a>.</td></tr><tr><td><strong>Connect over MCP</strong></td><td>Setup for the Mayhem MCP server.</td></tr><tr><td><strong>Command line</strong></td><td><code>scripts/mayhem.mjs</code> commands.</td></tr><tr><td><strong>C++ library</strong></td><td>Export the routines as a C++ header for the robot.</td></tr><tr><td><strong>Project document</strong></td><td>The raw project JSON.</td></tr></tbody></table><p>Agents work tasks with the MCP tools <code>list_tasks</code>, <code>claim_task</code>, <code>propose_plan</code>, <code>report_progress</code> and <code>finish_task</code>, and can analyze logs, run scenarios and diff behavior with the others. See the <a href="https://github.com/ryanabraham1/Mayhem/blob/main/docs/SUITE_AGENTS.md" target="_blank" rel="noreferrer">suite agent guide</a>.</p><p>After an agent edits a routine, look at the field and graph, then preview it before running it on the robot.</p>',13)])])}const b=e(r,[["render",s]]);export{p as __pageData,b as default};
